package com.example.lending.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.UUID;

@Entity
@Table(name = "book")
public class BookJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String title;

    @Column(nullable = false)
    private String status;

    protected BookJpaEntity() {
    }

    public BookJpaEntity(UUID id, String title, String status) {
        this.id = id;
        this.title = title;
        this.status = status;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public String getStatus() {
        return status;
    }
}
package com.example.lending.adapter.out.persistence;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

public interface BookJpaRepository extends JpaRepository<BookJpaEntity, UUID> {

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select b from BookJpaEntity b where b.id = :id")
    Optional<BookJpaEntity> findByIdForUpdate(@Param("id") UUID id);

    @Query("select b from BookJpaEntity b "
            + "where locate(lower(:keyword), lower(b.title)) > 0 "
            + "order by b.title asc, b.id asc")
    List<BookJpaEntity> findByTitleContainingIgnoreCase(@Param("keyword") String keyword);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.Book;
import com.example.lending.domain.BookStatus;

class BookMapper {

    Book toDomain(BookJpaEntity entity) {
        return Book.reconstitute(entity.getId(), entity.getTitle(), BookStatus.valueOf(entity.getStatus()));
    }

    BookJpaEntity toEntity(Book book) {
        return new BookJpaEntity(book.getId(), book.getTitle(), book.getStatus().name());
    }
}
