import com.example.lending.domain.Book;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class BookPersistenceAdapter implements LoadBookPort, SaveBookPort, SearchBooksPort {

    private final BookJpaRepository bookJpaRepository;
    private final BookMapper bookMapper = new BookMapper();

    public BookPersistenceAdapter(BookJpaRepository bookJpaRepository) {
        this.bookJpaRepository = bookJpaRepository;
    }

    @Override
    public Optional<Book> loadBook(UUID bookId) {
        return bookJpaRepository.findById(bookId).map(bookMapper::toDomain);
    }

    @Override
    public Optional<Book> loadBookForUpdate(UUID bookId) {
        return bookJpaRepository.findByIdForUpdate(bookId).map(bookMapper::toDomain);
    }

    @Override
    public void saveBook(Book book) {
        bookJpaRepository.save(bookMapper.toEntity(book));
    }

    @Override
    public List<Book> searchBooksByTitle(String keyword) {
        return bookJpaRepository.findByTitleContainingIgnoreCase(keyword).stream()
                .map(bookMapper::toDomain)
                .toList();
    }
}
