package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_an_available_book_returns_409() throws Exception {
        String bookId = registerBook("Free Book");
        String memberId = registerMember("이서연");

        reserve(bookId, memberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_book_on_loan_returns_position_starting_at_one() throws Exception {
        String bookId = registerBook("Popular Book");
        loanBook(bookId, registerMember("최도윤"));

        reserve(bookId, registerMember("정하준"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").isNotEmpty())
                .andExpect(jsonPath("$.position").value(1));
    }

    @Test
    void later_reservations_queue_behind_earlier_ones() throws Exception {
        String bookId = registerBook("Queued Book");
        loanBook(bookId, registerMember("holder"));
        String first = registerMember("first");
        String second = registerMember("second");
        reserve(bookId, first).andExpect(status().isCreated());
        reserve(bookId, second)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/" + bookId + "/reservations"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].memberId").value(first))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[1].memberId").value(second))
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void member_cannot_reserve_the_same_book_twice() throws Exception {
        String bookId = registerBook("Twice Reserved");
        loanBook(bookId, registerMember("holder"));
        String memberId = registerMember("중복");
        reserve(bookId, memberId).andExpect(status().isCreated());

        reserve(bookId, memberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void discarded_book_cannot_be_reserved() throws Exception {
        String bookId = registerBook("Discarded Reserve");
        loanBook(bookId, registerMember("holder"));
        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        reserve(bookId, registerMember("late"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_unknown_book_returns_404() throws Exception {
        reserve(UUID.randomUUID().toString(), registerMember("ghost"))
                .andExpect(status().isNotFound());
    }

    @Test
    void reserving_with_unknown_member_returns_404() throws Exception {
        String bookId = registerBook("Unknown Member Reserve");
        loanBook(bookId, registerMember("holder"));

        reserve(bookId, UUID.randomUUID().toString())
                .andExpect(status().isNotFound());
    }

    @Test
    void listing_reservations_for_unknown_book_returns_404() throws Exception {
        mockMvc.perform(get("/books/" + UUID.randomUUID() + "/reservations"))
                .andExpect(status().isNotFound());
    }

    @Test
    void non_first_reserver_cannot_borrow_after_return() throws Exception {
        String bookId = registerBook("Held For First");
        String holderLoanId = loanBook(bookId, registerMember("holder"));
        String first = registerMember("first");
        String second = registerMember("second");
        reserve(bookId, first).andExpect(status().isCreated());
        reserve(bookId, second).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, second))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
    }

    @Test
    void first_reserver_borrows_after_return_and_is_consumed() throws Exception {
        String bookId = registerBook("Handed Over");
        String holderLoanId = loanBook(bookId, registerMember("holder"));
        String first = registerMember("first");
        String second = registerMember("second");
        reserve(bookId, first).andExpect(status().isCreated());
        reserve(bookId, second).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, first))
                .andExpect(status().isCreated());

        mockMvc.perform(get("/books/" + bookId + "/reservations"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(second))
                .andExpect(jsonPath("$[0].position").value(1));
    }

    @Test
    void next_reserver_becomes_first_after_the_queue_head_borrows() throws Exception {
        String bookId = registerBook("Passed Along");
        String holderLoanId = loanBook(bookId, registerMember("holder"));
        String first = registerMember("first");
        String second = registerMember("second");
        reserve(bookId, first).andExpect(status().isCreated());
        reserve(bookId, second).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());
        String firstLoanId = loanBook(bookId, first);
        mockMvc.perform(post("/loans/" + firstLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, second))
                .andExpect(status().isCreated());
    }

    @Test
    void reserved_book_is_still_loanable_by_anyone_when_queue_is_empty() throws Exception {
        String bookId = registerBook("Unreserved After Return");
        String holderLoanId = loanBook(bookId, registerMember("holder"));
        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, registerMember("anyone")))
                .andExpect(status().isCreated());
    }

    private org.springframework.test.web.servlet.ResultActions reserve(String bookId, String memberId)
            throws Exception {
        return mockMvc.perform(post("/books/" + bookId + "/reservations")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"memberId\":\"" + memberId + "\"}"));
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(loanRequest(bookId, memberId))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private org.springframework.test.web.servlet.ResultActions loanRequest(String bookId, String memberId)
            throws Exception {
        return mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}"));
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(registered);
        return book.get("id").asText();
    }
}
