        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, first))
                .andExpect(status().isCreated());

        mockMvc.perform(get("/books/" + bookId + "/reservations"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(second))
                .andExpect(jsonPath("$[0].position").value(1));
    }

    @Test
    void next_reserver_becomes_first_after_the_queue_head_borrows() throws Exception {
        String bookId = registerBook("Passed Along");
        String holderLoanId = loanBook(bookId, registerMember("holder"));
        String first = registerMember("first");
        String second = registerMember("second");
        reserve(bookId, first).andExpect(status().isCreated());
        reserve(bookId, second).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());
        String firstLoanId = loanBook(bookId, first);
        mockMvc.perform(post("/loans/" + firstLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, second))
                .andExpect(status().isCreated());
    }

    @Test
    void reserved_book_is_still_loanable_by_anyone_when_queue_is_empty() throws Exception {
        String bookId = registerBook("Unreserved After Return");
        String holderLoanId = loanBook(bookId, registerMember("holder"));
        mockMvc.perform(post("/loans/" + holderLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(loanRequest(bookId, registerMember("anyone")))
                .andExpect(status().isCreated());
    }

